import { StrictMode, useEffect } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter, Routes, Route } from 'react-router-dom'
import './index.css'
import { initializeI18nSync, supportedLanguages, defaultLanguage, localeFromPath } from './i18n/config'
import App from './App.jsx'
import BlogIndex from './pages/BlogIndex.jsx'
import VideoPlayerLanding from './pages/VideoPlayerLanding.jsx'
import GuidesIndex from './pages/GuidesIndex.jsx'
import Article from './pages/Article.jsx'
import InApp from './pages/InApp.jsx'

const root = createRoot(document.getElementById('root'));

// Check if we were redirected from 404.html
const redirectPath = sessionStorage.getItem('redirectPath');
if (redirectPath) {
  window.history.replaceState(null, '', redirectPath);
  sessionStorage.removeItem('redirectPath');
}

// Language comes from the URL, decided once at boot, before the router even
// mounts, so the very first render (and thus the prerender snapshot for that
// URL) is already in the right language. No post-mount language flash/swap.
initializeI18nSync(localeFromPath(window.location.pathname));

/** Sets <html lang> for whichever locale branch matched. */
function LocaleFrame({ lang, children }) {
  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);
  return children;
}

// Same route tree for every locale; video_player is English-only (excluded
// from this i18n pass), so it's only registered on the unprefixed branch.
const siteRoutes = (includeVideoPlayer) => (
  <Routes>
    <Route path="blog" element={<BlogIndex />} />
    {/* Every /blog/<slug> comes from the imported content pack */}
    <Route path="blog/:slug" element={<Article type="blog" />} />
    <Route path="guides" element={<GuidesIndex />} />
    <Route path="guides/:slug" element={<Article type="guide" />} />
    {includeVideoPlayer && <Route path="video_player" element={<VideoPlayerLanding />} />}
    {includeVideoPlayer && <Route path="video_player/contact" element={<VideoPlayerLanding />} />}
    {includeVideoPlayer && <Route path="video_player/privacy" element={<VideoPlayerLanding />} />}
    <Route path="inapp" element={<InApp />} />
    <Route path="*" element={<App />} />
  </Routes>
);

// One prefixed branch per translated locale, then the unprefixed English
// branch last so it acts as the catch-all. Generated from supportedLanguages
// rather than written out, so a new locale needs no route of its own.
const SiteRouter = (
  <Routes>
    {supportedLanguages.filter((lang) => lang !== defaultLanguage).map((lang) => (
      <Route
        key={lang}
        path={`/${lang}/*`}
        element={<LocaleFrame lang={lang}>{siteRoutes(false)}</LocaleFrame>}
      />
    ))}
    <Route path="/*" element={<LocaleFrame lang={defaultLanguage}>{siteRoutes(true)}</LocaleFrame>} />
  </Routes>
);

// Render immediately
const AppWrapper = import.meta.env.DEV ? (
  <StrictMode>
    <BrowserRouter>
      {SiteRouter}
    </BrowserRouter>
  </StrictMode>
) : (
  <BrowserRouter>
    {SiteRouter}
  </BrowserRouter>
);

root.render(AppWrapper);
